solution:
import hashlib
import hmac

def connexion(comptes, nom, mdp):
    for compte in comptes:
        if compte["nom"] == nom:
            calcul = hashlib.sha256((compte["sel"] + mdp).encode("utf-8")).hexdigest()
            if hmac.compare_digest(calcul, compte["empreinte"]):
                return "accepté"
            return "refusé"
    return "refusé"
